function MResalatServiceIcon(props: ComponentProps<typeof BaseMResalatServiceIcon>) {
  return <BaseMResalatServiceIcon {...props} eager />;
}

export type FullPageSpec = {
  key: string;
  sectionKey: string;
  sectionTitle: string;
  tone?: 'paper' | 'soft' | 'ink' | 'cyan';
  className?: string;
  content: ReactNode;
};

