function page(sectionKey: string, sectionTitle: string, key: string, content: ReactNode, tone: FullPageSpec['tone'] = 'paper', className?: string): FullPageSpec {
  return { sectionKey, sectionTitle, key, content, tone, className };
}

function opener(index: number, tone: FullPageSpec['tone'] = 'ink'): FullPageSpec {
  const item = publicationSections[index - 1];
  return page(item[0], item[1], `${item[0]}-opener`, <SectionCover number={index} title={item[1]} english={item[2]} statement={sectionStatements[index - 1]} />, tone, 'catalog-book-chapter-opener');
}

function RuleGrid({ items, columns = 3 }: { items: Array<{ title: string; text: string; code?: string; tone?: string }>; columns?: 2 | 3 | 4 }) {
  return <div className={`catalog-book-rule-grid cols-${columns}`}>{items.map((item, index) => <article className={item.tone ? `tone-${item.tone}` : ''} key={`${item.title}-${index}`}><span>{(index + 1).toLocaleString('fa-IR')}</span><h3>{item.title}</h3>{item.code && <code dir="ltr">{item.code}</code>}<p>{item.text}</p></article>)}</div>;
}

function EditorialColumns({ children }: { children: ReactNode }) {
  return <div className="catalog-book-editorial-columns">{children}</div>;
}

function Bullets({ items }: { items: string[] }) {
  return <ul className="catalog-book-bullets">{items.map((item) => <li key={item}><i /><span>{item}</span></li>)}</ul>;
}

function MiniCode({ children }: { children: string }) {
  return <pre className="catalog-book-code" dir="ltr"><code>{children}</code></pre>;
}

function StatusStrip() {
  const statuses = [
    ['official', 'دانش رسمی', 'پاسخ مستند و پایدار'],
    ['live', 'داده زنده', 'وضعیت جاری سامانه'],
    ['ai', 'توضیح هوش مصنوعی', 'تفسیر قابل تمایز'],
    ['recommendation', 'پیشنهاد', 'اقدام بعدی غیرقطعی'],
  ];
  return <div className="catalog-book-trust-strip">{statuses.map(([key, title, text]) => <article className={`trust-${key}`} key={key}><i /><strong>{title}</strong><p>{text}</p><code dir="ltr">trust.{key}</code></article>)}</div>;
}

function IdentityGrid({ start, end }: { start: number; end: number }) {
  return <div className="catalog-book-identity-grid">{ecosystemIdentityServices.slice(start, end).map((service) => <article key={service.id}><MResalatServiceIcon service={service} size={64} /><div><strong>{service.titleFa}</strong><bdi dir="ltr">{service.titleEn}</bdi><span className={service.identity.source === 'official-asset' ? 'official' : 'designed'}>{service.identity.source === 'official-asset' ? 'دارایی رسمی' : 'طراحی MResalat System'}</span><small><bdi dir="ltr">{service.id}</bdi> · {service.source.type}</small></div></article>)}</div>;
}

function DomainPage({ domain, index }: { domain: (typeof exampleDomains)[number]; index: number }) {
  const routes = exampleRoutes.filter((route) => route.domain === domain.key);
  const services = routes.map((route) => serviceCatalog.find((item) => item.id === route.serviceId)!).filter(Boolean);
  const identity = ecosystemServiceById[domain.ecosystemServiceId];
  const risk = [...new Set(services.map((item) => item.riskLevel))].sort();
  const patterns = [...new Set(services.flatMap((item) => item.componentKeys.slice(-2)))].slice(0, 6);
  const screenshotByDomain: Record<string, string> = {
    membership: 'membership-domain', mhami: 'mhami-domain', mbazar: 'mbazar-home', learning: 'learning-domain', mhesam: 'mhesam-domain',
    'heavenly-resalat': 'heavenly-domain', msalamat: 'health-domain', mbime: 'insurance-domain', auxiliary: 'auxiliary-domain', rahyar: 'rahyar-domain', banking: 'banking-domain', communication: 'communication-domain',
  };
  return <div className="catalog-book-domain-page"><header><span>دامنه {(index + 1).toLocaleString('fa-IR')}</span><MResalatServiceIcon service={identity} size={64} /><div><h1>{domain.titleFa}</h1><bdi dir="ltr">{domain.titleEn}</bdi><p>{domain.description}</p></div></header><ScreenshotFigure src={`/catalog-book-generated/${screenshotByDomain[domain.key]}.png`} alt={`نمونه محصول ${domain.titleFa}`} number={`۱۵-${index + 1}`} title={`نمای پیاده‌سازی‌شده دامنه ${domain.titleFa}`} /><div className="catalog-book-domain-summary"><Stat value={routes.length} label="مسیر ممیزی‌شده" /><Stat value={risk.join(' / ')} label="سطوح ریسک" /><Stat value={identity.identity.source === 'official-asset' ? 'رسمی' : 'طراحی‌شده'} label="منبع هویت" /></div><div className="catalog-book-pattern-tags">{patterns.map((pattern) => <code dir="ltr" key={pattern}>{pattern}</code>)}</div></div>;
}

function RouteMatrixPage({ chapter }: { chapter: (typeof serviceCatalogChapters)[number] }) {
  const routes = serviceCatalog.filter((route) => route.chapter === chapter.id);
  return <div className="catalog-book-route-page"><PageTitle kicker={`۱۶ · فصل ${chapter.id.toLocaleString('fa-IR')}`} title={chapter.titleFa} english={chapter.titleEn} lead={`${routes.length.toLocaleString('fa-IR')} مسیر ممیزی‌شده این فصل با وضعیت شواهد، سطح ریسک، مرز توقف و الگوی اصلی ثبت شده‌اند.`} /><div className={`catalog-book-route-matrix dense rows-${routes.length}`}><div className="catalog-book-route-row is-head"><span>ش.</span><span>مسیر / route</span><span>وضعیت</span><span>ریسک</span><span>مرز توقف / الگوی اصلی</span></div>{routes.map((route, index) => <div className="catalog-book-route-row" key={route.id}><strong>{(index + 1).toLocaleString('fa-IR')}</strong><div><b>{route.titleFa}</b><bdi dir="ltr">{route.titleEn}</bdi><a href={route.demoHref} dir="ltr">{route.demoHref}</a></div><span>{route.verificationStatus}</span><RiskBadge level={route.riskLevel} /><div><p>{route.safeStopFa}</p><small dir="ltr">{route.surfaceKind} · {route.componentKeys.slice(-2).join(' + ')}</small></div></div>)}</div><footer className="catalog-book-route-proof"><span>منبع</span><bdi dir="ltr">example-route-registry.ts → service-catalog.ts</bdi><strong>{routes.length.toLocaleString('fa-IR')} / {routes.length.toLocaleString('fa-IR')}</strong></footer></div>;
}

